import React from 'react';
import LoginForm from '../app/components/forms/LoginForm'
import RegisterForm from '../app/components/forms/RegisterForm'
import { Link } from 'react-router-dom';

function AuthPage() {
  return (
    <div className="container trang-ng-nhp">
      <p className="trang-ch-t-i-kho-n">
        <Link to="/">Trang chủ</Link> / Tài Khoản
      </p>

      {/* Tách biệt hai form Đăng nhập và Đăng ký */}
      <div className="auth-forms-wrapper">
        <LoginForm />
        <RegisterForm />
      </div>

      {/* Nếu cần thêm các yếu tố khác từ trang HTML đăng nhập */}
      {/* <div className="text-wrapper-6">Nội Dung Trang [Ẩn]</div> */}
      {/* ... */}
    </div>
  );
}

export default AuthPage;
